PROGRAM elevator
VAR_INPUT
    CallUp : BOOL;
    CallDown : BOOL;
    DoorClosed : BOOL;
    AtTop : BOOL;
    AtBottom : BOOL;
END_VAR
VAR_OUTPUT
    MotorUp : BOOL;
    MotorDown : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    Bottom := 0;
    Up := 1;
    Top := 2;
    Down := 3;
END_VAR

CASE State OF
    Bottom:
        IF CallUp AND DoorClosed THEN
            State := Up;
        END_IF;
    Up:
        IF CallDown AND DoorClosed AND NOT AtTop THEN
            State := Down;
        ELSIF AtTop OR NOT DoorClosed THEN
            State := Top;
        END_IF;
    Top:
        IF CallDown AND DoorClosed THEN
            State := Down;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := Bottom;
        END_IF;
    Down:
        IF CallUp AND DoorClosed AND NOT AtBottom THEN
            State := Up;
        ELSIF AtBottom OR NOT DoorClosed THEN
            State := Bottom;
        END_IF;
END_CASE;

CASE State OF
    Up:
        MotorUp := TRUE;
        MotorDown := FALSE;
    Down:
        MotorUp := FALSE;
        MotorDown := TRUE;
