VAR CONSTANT
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR
VAR
    State : INT;
END_VAR
VAR TON
    T1;
END_VAR

T1(IN := TRUE, PT := T#1s);

CASE State OF
    0:
        IF NOT EStop THEN
            State := 0;
        ELSIF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1:
        IF NOT EStop OR Level < LIQ_MIN THEN
            State := 0;
        ELSEIF Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2:
        IF NOT EStop OR Level < LIQ_MIN OR Temp >= TEMP_SET THEN
            State := 0;
        ELSIF Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3:
        IF NOT EStop OR Level < LIQ_MIN OR Temp >= TEMP_SET OR T1.Q >= PT_REACT THEN
            State := 0;
        ELSIF Temp >= TEMP_SET THEN
            State := 4;
        END_IF;

    4:
        IF NOT EStop OR Level < LIQ_MIN OR Level <= LVL_LOW THEN
            State := 0;
        ELSEIF Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

CASE State OF
    1:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
