            IF Temp >= TEMP_SET AND Level >= LIQ_MIN THEN
                State := 3;
            END_IF;
        3:
            IF T#3s <= PT_REACT THEN
                State := 4;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
            END_IF;
    END_CASE;
END_IF;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
