        IF Level >= LVL_HIGH THEN
            FillValve := TRUE;
        ELSE
            FillValve := FALSE;
        END_IF;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        IF Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;
        DrainValve := FALSE;
    3:
        IF Level >= LIQ_MIN THEN
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;
        DrainValve := FALSE;
    4:
        IF Level <= LVL_LOW THEN
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := FALSE;
        END_IF;
    ELSE
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
END_CASE;

