VAR TON
    T1, T2;
END_VAR

CASE State OF
    0: // Idle
        IF EStop THEN
            State := 0;
        ELSIF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := Level < LVL_HIGH;
        IF EStop OR Level >= LVL_HIGH THEN
            State := 2;
        END_IF;

    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF EStop OR Temp >= TEMP_SET THEN
            State := 3;
        END_IF;

    3: // React
        Heater := TRUE;
        Agitator := TRUE;
        T1(IN := TRUE, PT := T#3s);
        IF EStop OR T1.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        DrainValve := Level > LVL_LOW;
        IF EStop OR Level <= LVL_LOW THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0: IF Level >= LVL_HIGH THEN State := 2 ELSE State := 1 END_IF;
        1: IF Level >= LVL_HIGH THEN State := 2 END_IF;
        2: IF Temp >= TEMP_SET AND State >= 3 THEN State := 3 ELSE IF Level < LIQ_MIN OR Temp >= TEMP_SET + 10 THEN State := 2 END_IF END_IF;
        3: IF State >= 3 + PT_REACT THEN State := 4 END_IF;
        4: IF Level <= LVL_LOW THEN State := 0 END_IF;
    END_CASE
END_IF;

CASE State OF
    0: FillValve := FALSE; Heater := FALSE; Agitator := FALSE; DrainValve := FALSE;
    1: FillValve := Level < LVL_HIGH; Heater := FALSE; Agitator := FALSE; DrainValve := FALSE;
    2: FillValve := FALSE; Heater := Temp < TEMP_SET; Agitator := Temp < TEMP_SET; DrainValve := FALSE;
    3: FillValve := FALSE; Heater := TRUE; Agitator := TRUE; DrainValve := FALSE;
    4: FillValve := FALSE; Heater := FALSE; Agitator := FALSE; DrainValve := Level > LVL_LOW;
END_CASE;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : INT := 3;
END_VAR
VAR
    State : INT;
END_VAR
VAR_TON
    T1 : TON;
END_VAR

T1(IN := TRUE, PT := T#1s);

CASE State OF
    0:  // Idle
        IF EStop THEN
            State := 0;
        ELSIF StartBatch AND Level >= LIQ_MIN THEN
            State := 1;
        END_IF;

    1:  // Fill
        FillValve := Level < LVL_HIGH AND EStop;
        IF NOT EStop OR Level >= LVL_HIGH OR Level < LIQ_MIN THEN
            State := 0;
        END_IF;

    2:  // Heat
        Heater := Temp < TEMP_SET AND EStop;
        Agitator := EStop;
        IF NOT EStop OR Temp >= TEMP_SET OR Level < LIQ_MIN THEN
            State := 0;
        END_IF;

    3:  // React
        Heater := Temp < TEMP_SET AND EStop;
        Agitator := EStop;
        IF NOT EStop OR Temp >= TEMP_SET OR T1.T >= PT_REACT OR Level < LIQ_MIN THEN
            State := 0;
        END_IF;

    4:  // Drain
        DrainValve := Level > LVL_LOW AND EStop;
        IF NOT EStop OR Level <= LVL_LOW OR Level < LIQ_MIN THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM garage
