    Count := MIN(Count + 1, CAP);
ELSIF ExitSensor AND (Count > 0) THEN
    Count := Count - 1;
END_IF;

PrevEntry := EntrySensor;
PrevExit := ExitSensor;

FullSign := Count >= CAP;
EntryBarrierOpen := EntryReq AND (Count < CAP);

