    MainK  : BOOL;
    StarK  : BOOL;
    DeltaK : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_STAR : TIME := T#3s;
END_VAR

CASE State OF
    0:
        IF NOT EStop THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        IF NOT EStop OR StopPB THEN
            State := 0;
        ELSEIF T#0s >= PT_STAR THEN
            State := 2;
        END_IF;
    2:
