    1:
        MainK := TRUE;
        StarK := TRUE;
        DeltaK := FALSE;
    2:
        MainK := TRUE;
        StarK := FALSE;
        DeltaK := TRUE;
    DEFAULT:
        MainK := FALSE;
        StarK := FALSE;
        DeltaK := FALSE;
END_CASE;

END_PROGRAM

