    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    IDLE : INT := 0;
    FILLING : INT := 1;
    DRAINING : INT := 2;
    LOW : INT := 10;
    HIGH : INT := 90;
END_VAR

IF NOT EStop THEN
    State := IDLE;
ELSIF Level >= HIGH AND State <> FILLING THEN
    State := DRAINING;
ELSIF Level <= LOW AND State <> DRAINING THEN
    State := IDLE;
ELSIF StartCycle AND Level < HIGH AND State = IDLE THEN
    State := FILLING;
END_IF;

CASE State OF
    IDLE:
        Pump := FALSE;
        Valve := FALSE;
    FILLING:
        Pump := TRUE;
        Valve := FALSE;
    DRAINING:
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

