    StartPB : BOOL;
    StopPB  : BOOL;
    EStop   : BOOL;
END_VAR
VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

CASE State OF
    0:
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        ELSIF StartPB AND EStop THEN
            State := 1;
        END_IF;
    1:
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        ELSIF EStop AND T#0s >= PT_SEQ THEN
            State := 2;
        END_IF;
    2:
        IF (NOT EStop) OR StopPB THEN
            State := 0;
        END_IF;
END_CASE;

CASE State OF
    1:
        C2 := TRUE;
        C1 := FALSE;
    2:
        C2 := TRUE;
