END_VAR
VAR
    State : INT;
END_VAR
VAR CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    State := 0;
ELSIF StopPB THEN
    State := 0;
ELSIF StartPB AND (State = 0) AND EStop THEN
    State := 1;
ELSIF StartPB AND (State = 1) AND EStop THEN
    State := 2;
ELSIF StartPB AND (State = 2) AND EStop THEN
    State := 3;
END_IF;

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

